#ifndef __ASRM_FMT_ID_HELPER_H__
#define __ASRM_FMT_ID_HELPER_H__

static inline const char *depth2str(unsigned int depth)
{
	switch (depth) {
	case 0:  return "";
	case 1:  return "  ";
	case 2:  return "    ";
	case 3:  return "      ";
	case 4:  return "        ";
	case 5:
	default: return "          ";
	}
}

#define show_struct(_depth, _title, _print_func, _member_func, _para1) \
	do { \
		unsigned int cur_depth = (_depth); \
		_print_func("%s%s = {\n", depth2str(cur_depth), (_title)); \
		(_member_func)(cur_depth + 1, (_para1)); \
		_print_func("%s}\n", depth2str(cur_depth)); \
	} while (0)


#endif /* __ASRM_FMT_ID_HELPER_H__ */
